INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(55000, 0, 0, 0, 0, 0, 0, 0, 0, 'About time, I was gettin\' scared, thought I might\'a lost em!$B$BThey are a bit more dirty than I remember though, for muckin\' up my tools yer gonna get a silver less, no hard feelings!', 0),
(55002, 0, 0, 0, 0, 0, 0, 0, 0, 'You the new delivery kid from Razor Hill? Didn\'t really think that old orc would get the order here that quick. You better not tell him we\'ve just been giving him flak! He might start to think he\'s doing too good a job, or something!', 0),
(55003, 0, 0, 0, 0, 0, 0, 0, 0, '<The goblin quickly tinkers with the acquired scales>$B$BThe energy in these babies is off the chart! My hunches were correct, maybe this will work!$B$BOh, my chances of gettin\' promoted to Head Technician just went up, about fifteen percent for sure!', 0),
(55006, 0, 0, 0, 0, 0, 0, 0, 0, 'Some green gnome was using it to power a giant robot? What a waste!$B$B<Grimzlow takes the capacitor and inserts it to the machine behind him.>$B$BThere, this should work well enough. If it doesn\'t explode, that is. Thanks for the hussle by the way. Feel free to take one of these prototypes as reward, and don\'t stick your fingers into any turning pieces if you want to keep them.', 0),
(55019, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'re looking for Zuul? Well that would be me, what\'s this?', 0),
(55020, 0, 0, 0, 0, 0, 0, 0, 0, 'What is it you require from Commander Ruag? It had better be important.', 0),
(55021, 0, 0, 0, 0, 0, 0, 0, 0, 'It seems you\'ve done well, I\'ll be pleased to have fewer orcs go missing.', 0),
(55022, 0, 0, 0, 0, 0, 0, 0, 0, 'Really? I didn\'t actually expect the chance to go.$B$BThis means a lot to me, it\'s the chance to correct wrongs and make rights.$B$BI realize that there should be no competition between brothers and getting this note only serves to remind me that we should be proud of who we are.', 0),
(55023, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, a letter?$B$B<Rugnar begins to read intently.>$B$BWell, this is unexpected news, I must offer my thanks for everything you\'ve done. The last thing I expected was a letter back so quickly. Take this, for all of the troubles.', 0),
(55041, 0, 0, 0, 0, 0, 0, 0, 0, 'Hey, this seems to be it. The damage is certainly going to hurt the resell value when I\'m done reading it.', 0),
(55042, 0, 0, 0, 0, 0, 0, 0, 0, '<Shak slips the ring on his own finger and chuckles.>$B$BFinally, that idiot had what was coming to him. Maybe now people will stop calling me by that name!', 0),
(55044, 0, 0, 0, 0, 0, 0, 0, 0, 'Hey there, nice view huh?$B$BOh, the boss sent you?', 0),
(55045, 0, 0, 0, 0, 0, 0, 0, 0, 'What\'s all this? Axel sent this?$B$BI guess he is working out there after all. This is quite a bit, fine, tell him to keep doing whatever he\'s doing then!', 0),
(55046, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, finally a piece of this rare ore. Let me see if it can be used, thanks $N.', 0),
(55047, 0, 0, 0, 0, 0, 0, 0, 0, 'Wow, I haven\'t seen these in a long, long time. This means a lot to me, $N.', 0),
(80219, 0, 0, 0, 0, 0, 0, 0, 0, 'Nice job, $N. I\'ll be sure to tell the others of your help.', 0),
(80386, 4, 1, 0, 0, 0, 0, 0, 0, 'Your help is appreciated, sugar, keep them coming!', 0),
(55005, 0, 0, 0, 0, 0, 0, 0, 0, 'Nice job. He actually built the shredder, you say?$B$BGuess he was always smarter than he looked. I almost gave up on you and was about to put up a bounty. You can have the bounty reward instead.', 0),
(55036, 0, 0, 0, 0, 0, 0, 0, 0, '...Laz sent you? Oh, please don\'t break my knees! Anything but that...$B$BWait, you\'re here to help with the Yeti fur?$B$BWell, isn\'t that a relief? I could certainly use help.', 0),
(55037, 0, 0, 0, 0, 0, 0, 0, 0, 'I see you got the Yeti Fur. Let me box this up right quick to send to Laz!', 0),
(55038, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, that took long enough. Last time I deal with him. He\'s a horrible contractor.$B$BA goblin should know never to be late, especially not with me. Here, take the extra coin he gave me for actually getting me this fur.$B$BNo doubt you\'re responsible for it getting here at all. Without you, I\'d be out of a shipment of fancy cloaks.', 0),
(41303, 0, 0, 0, 0, 0, 0, 0, 0, 'Grizzby? No, he didn\'t leave Ratchet, atleast not by boat. But he did make it here, that\'s for sure.', 0),
(41304, 0, 0, 0, 0, 0, 0, 0, 0, '<Tacknazz reads the contract you found on the goblin. The further he reads, the redder his green skin becomes.>$B$BOh, those backstabbing, scab-munching troglodytes! Leaving the Venture Co. was the best thing Nert could\'ve ever done, I am sick and tired of their shady tactics. Not only have I lost all my precious jewelry, but also my best contractor, finding a replacement is going to take ages! Oh, Grizzby, you old bastard, you deserved better, much better...', 0),
(41767, 0, 0, 0, 0, 0, 0, 0, 0, 'You were in Tanaris and helped out Celdi? How wonderful, that woman is a true blessing! When she first flounced around Sparkwater Port my eyes almost flew out of my skull. A high administrator of the Bilgewater Cartel here, in our small town?! And she wants to join us?! It felt like I had just doubled all my lifesavings in a last effort try at the casino. After the disaster that was Blackstone Island, the Durotar Labor Union desperately needed an uplift in profit AND morale. The oil rig in Tanaris was an excellent idea, if I were to be so humble. With Slickwick at the helm, I just knew it\'d be a success.$B$BDespite that, the Venture Co.\'s continued sabotage and intrusion worry me. I fear their patience runs dry, Razdunk never was one to remain calm when he doesn\'t get his way. Keep your ears and eyes sharp, $N. The future won\'t be easy for us.', 0),
(40638, 0, 0, 0, 0, 0, 0, 0, 0, 'Nert sends yet another employee to me. Perfect, we need all the hands we can get.', 0),
(55026, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes? Oh.... HE sent you?$B$BFool was oh so eager to offer his assistance to the Horde for coin. He underestimated the pirates in the area and got himself sank.$B$BNow he wants to call in a favor from an age past, hah. Let\'s get this over with.', 0),
(55027, 0, 0, 0, 0, 0, 0, 0, 0, 'They\'ve been putting their hands on things that don\'t rightfully belong to them, it\'s time they paid the price, and a price they cannot link to me.', 0),
(55028, 0, 0, 0, 0, 0, 0, 0, 0, 'Look bud, we don\'t got any spare copper already, so beat it.', 0),
(55029, 0, 0, 0, 0, 0, 0, 0, 0, 'Not you again, don\'t tell me Pazzle is coming back to ask for something else.', 0),
(55030, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, ain\'t that a relief! I thought finding who was hunting us was going to be like finding a drop of water in the ocean, but here we are!', 0),
(55031, 0, 0, 0, 0, 0, 0, 0, 0, '<The goblin stares at the head of the orc.>$B$BWow, it must have taken a small army to take down Salt Tooth. Either that, or you are much stronger then I thought!', 0),
(55051, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, it certainly has been a while, you got any good news from Booty Bay?$B$BOh, they\'re on their way back? Oh and Revilgaz was upset huh? I don\'t blame him, heh.$B$BYou\'ve saved my crew from an unknown fate and I thank ye for that, $N. Please, take this cutlass, no point in swashbuckling if the ship is gone.', 0),
(55043, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh boy, this eases a Captain\'s mind, I was worried some people might go looking before I could find the blasted thing. Here, let\'s share a drink!', 0),
(55048, 0, 0, 0, 0, 0, 0, 0, 0, 'You answered the board did you?$B$BDamn prisoner was able to tunnel his way out of the last hole. We had to board it up after he got out into the ocean. Good thing he\'s dealt with.', 0),
(55007, 0, 0, 0, 0, 0, 0, 0, 0, 'Look at all this barren nothingness in Azshara!$B$BWhat do you mean theres stuff all around us? I meant as in nobody is doing any work here, all this wasted potential. Such a shame that I\'m here doing this rather than setting up factories all over, heh.', 0),
(55008, 0, 0, 0, 0, 0, 0, 0, 0, 'This dead goblin seems to fit the description of a goblin being dead in elvish ruins. He is covered in marks of struggle, bruises, and puncture wounds.$B$BYou begin your search for the Surveying Gear amongst the scattered bones and blood.', 0),
(55009, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, just as I suspected, dead... Wait, he lost it?!$B$BDamn you Frix, you blasted, good for nothing, worthless...', 0),
(55010, 0, 0, 0, 0, 0, 0, 0, 0, 'Did you find it? Oh...$B$BDamn I was getting ready to pack it up and start heading into exile, you really saved my hide here kid, and BIG time. Here, this is Frix\'s necklace. He gave it to me before he headed out, aparently the metal messed with the survey gear. It\'s probably coated in bad luck, last thing I want is to keep it.', 0),
(55014, 0, 0, 0, 0, 0, 0, 0, 0, 'Finally got it huh? Here, let\'s try and see if we can get some energy off this thing.$B$B<Gazztoggle quickly begins his task, soon producing many small objects and devices. He takes quite a healthy amount of the powder and places it within one machine after the other. After a few minutes of trying, he seems to give up using the Essence.>$B$BDamn! Looks like this isn\'t actually viable. I\'d best come up with something else.', 0),
(55015, 0, 0, 0, 0, 0, 0, 0, 0, 'Glad you came back in one piece. Now, did you get those shards?!$B$B<The goblin greedily takes the ley-shards and begins to tinker with them. It is not long before the unstable shards crackle and fizzle, beginning to turn to dust.>$B$BDamned! These crystals are worthless, junk even, too unstable and not even in the good way...$B$BI\'m really going to have to use my noggin here.', 0),
(55016, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, took you long enough! Had trouble finding the blasted things? Oh well, gimme!$B$B<Gazztoggle takes the Antlers from you, quickly moving to test their power.>$B$BYes! Finally something! Who would have guessed this would be worth our time...$B$BThanks again, $N, for all you\'ve done.', 0),
(55017, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, didn\'t I send you to Azshara?$B$BDon\'t tell me you\'ve been in the tavern this entire time!$B$BThis is from Gazztoggle, I figured he had run with Sparkwater\'s money, I was getting ready to call up my people to go and give him a REAL visit.$B$BHe seems to have found some promising results at least.', 0),
(55018, 0, 0, 0, 0, 0, 0, 0, 0, 'Wait... You actually pulled it off?$B$BI can\'t believe you managed to interfere with the Dragonkin in such a way! Haha!$B$BWith this staff I could power Sparkwater for weeks, maybe even set up my own shop here...$B$BOh, take this!', 0),
(40789, 0, 0, 0, 0, 0, 0, 0, 0, 'A Kul Tiran paladin gave you this book?$B$BIn Kul Tiras, the Holy Light is not as widespread as it is in Stormwind and Lordaeron; places where the tradition of the faith has long been established.$B$BYet I am gladdened to see that our church has touched the heart of such a worthy man. I will make sure all its contents are kept safe in our archives.$B$BThank you, and may the Light ever be with you, $N.', 0),
(40790, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, look at that, not even part of the Old Alliance, and still making yourself useful as a $R. Perhaps you do have it cut out to be part of the navy after all.', 0),
(40791, 0, 0, 0, 0, 0, 0, 0, 0, 'Well, I was right to trust my hands in you. Perhaps not all is so bad in this \'New Alliance\' afterall, or so I was believed to think you were all just too lazy to work on behalf of this war.$B$BYou\'ve done well, and for your hard work, you\'ve earned this commendation, wear it with pride soldier.', 0),
(40792, 0, 0, 0, 0, 0, 0, 0, 0, 'The Aqua Core, and even more potent than I had hoped!$B$BIn this arid land of beasts, mongrels and demi-humans, I dared not hold faith in assistance from anyone. But now, my control of the tidal elements is secured.$B$BYou have my thanks, $C.', 0),
(40793, 0, 0, 0, 0, 0, 0, 0, 0, 'The souls of our honored dead sing of your name, $C.$B$BBut there shall be no peace for me, not until all of Lord Daelin\'s murderers are dead and their accursed nations gone with them.', 0),
(40794, 0, 0, 0, 0, 0, 0, 0, 0, 'Alverold lives?! Tides be thanked!$B$BWith the fall of Lord Daelin, we thought the western cause lost. Indeed, many in Kul Tiras have elected to divert our attention north.$B$BIt will not be easy to persuade them to support the Kalimdor Expedition again; it is far more likely that they will demand Alverold\'s return for his assistance in the northern realms instead.$B$BStill, I will do what I can and send word to Alverold once I have news.$B$BYou have Kul Tiras\' gratitude, $N.', 0),
(40672, 0, 0, 0, 0, 0, 0, 0, 0, 'If my duties did not keep me here, I would have gladly joined you in the thrill of battle.$B$BYou have delivered the Warchief\'s reckoning to our enemies. For that, the whole Horde shall sing your praise.', 0),
(40673, 0, 0, 0, 0, 0, 0, 0, 0, 'It is done, then. With their chain of command gone, it might take months for their expedition to re-organize.$B$BWe shall not give them such a luxury.', 0),
(40674, 0, 0, 0, 0, 0, 0, 0, 0, '<Dar\'nakk holds the head of Alverold aloft.>$B$BHere you are, pinkskin. Burn in your hell, knowing it was the Horde who vanquished you.$B$BWe orcs are here to stay, you make sure you remember that when you bring my regards to Daelin!$B$B<Dar\'nakk looks back to you.>$B$BNow, you and I shall have a talk.', 0),
(40675, 0, 0, 0, 0, 0, 0, 0, 0, 'I feel sorrow in having to be forced to violence a second time in so few years.$B$BBut I feel no shame in ordering the deaths of our enemies when our sovereignty is infringed. A war in the defense of our people is a just war.$B$BTake pride in your bravery, $N! For I now name you Champion of the Horde and give you this mighty signet as recognition of your triumphs! Bear it with honor!', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(55000, 0, 0, 'You got em yet? Or you just waitin\' around?', 0),
(55002, 0, 0, 'What, was there anything that I could help with?', 0),
(55003, 0, 0, 'Find those lizards yet? I said they were at Thunder Ridge!', 0),
(55006, 0, 0, 'Time is ticking, and there\'s no telling when disaster might strike.', 0),
(55019, 0, 0, 'Why hello there, stranger, what brings you to Stonard?', 0),
(55020, 0, 0, 'He is located within the large building in the encampment.', 0),
(55021, 0, 0, 'The Swamp has earned its name, has it not?', 0),
(55022, 0, 0, 'Have you heard word from my brother?', 0),
(55023, 0, 0, 'I wonder if my message reached him. I hope I get to see him soon...', 0),
(55041, 0, 0, 'Have you checked all of the heights? I got good sources saying he was there.', 0),
(55042, 0, 0, 'Any luck in finding him out there?', 0),
(55044, 0, 0, 'He\'s gotta be around here somewhere, keep looking!', 0),
(55045, 0, 0, 'Yeah? Any luck finding him?', 0),
(55046, 0, 0, 'The Ore should be a dark black color, go find it!', 0),
(55047, 0, 0, 'The Pirates can be trouble, but you look like you can handle yourself.', 0),
(80219, 0, 0, 'If there\'s one thing a goblin is always in need of, it\'s dynamite!$B$BWhether it\'s used to excavate, blow up enemies, or just to watch things go KABOOM!$B$BAnyways, bring me 20 heavy dynamite and I\'ll be sure to put in a good word for you. Be sure to bring me quality dynamite too.$B$BI don\'t care where you find it either, unless you were to find it off the corpse of a gnome. In that case, be sure to wipe it down with disinfectant before you bring it to me.$B$BGnomes have a characteristically unpleasant odor that I find, quite frankly, to be repulsive.', 0),
(80386, 1, 1, 'I never thought we\'d have a fresh start, and not in my wildest dreams I\'d think we\'d do that under the Horde\'s flag, but what do you know, here we are.$B$BWe currently are a small group of goblins that ran away with only scraps and dust in our pockets, but slowly we will make a name for ourselves, and if you want, you can be part of that.$B$BThe Labor Union grows day by day, goblins come our way to find a new meaning in life under the Horde\'s gaze, but we lack both means and resources.$B$BIf you wish to be part of the Union\'s future bring me a handful of Whirring Bronze Gizmos whenever you can. You will eventually get paid.', 0),
(55005, 0, 0, 'Any luck finding him?', 0),
(55036, 0, 0, 'Oh, where\'s the... Yes?$B$BCan\'t you see I\'m busy here!', 0),
(55037, 0, 0, 'Have you had any luck hunting the Yeti?', 0),
(55038, 0, 0, 'Welcome back to Sparkwater. Did you deal with Tarlo yet?', 0),
(41304, 0, 0, '$N, where have you been? Did you find my jewelry, and where did you leave Grizzby?', 0),
(41767, 0, 0, 'Either good news or no news, pal. Another bad errand would be the death of me!', 0),
(40638, 0, 0, 'Beat it, kid!', 0),
(55026, 0, 0, 'Is there something that I can help you with?', 0),
(55027, 0, 0, 'Have you thrown a wrench in their plans?', 0),
(55028, 0, 0, 'Yes?', 0),
(55029, 0, 0, 'Yes?', 0),
(55030, 0, 0, 'So... Did you figure anything out?', 0),
(55031, 0, 0, 'Having a hard time finding him? You\'re telling me.', 0),
(55051, 0, 0, 'Can I help you?', 0),
(55043, 0, 0, 'Have you found my sunken beauty\'s logbook yet?', 0),
(55048, 0, 0, 'What now?', 0),
(55007, 0, 0, 'Have you found him yet?', 0),
(55008, 0, 0, 'You find that lout yet?', 0),
(55009, 0, 0, 'Hmm?', 0),
(55010, 0, 0, 'Have you found the Surveying Gear yet?', 0),
(55014, 0, 0, 'Get to gathering that ghost dust, pal!', 0),
(55015, 0, 0, 'What, are the Naga being too much trouble?', 0),
(55016, 0, 0, 'What? Getting bored of searching for them?', 0),
(55017, 0, 0, 'He\'s in Sparkwater!', 0),
(55018, 0, 0, 'What? We\'re on the brink of greatness here, you gotta get that staff.', 0),
(40789, 0, 0, 'Light\'s blessings, $N. Have you come to join our service?', 0),
(40790, 0, 0, 'You get that food yet maggot?!', 0),
(40791, 0, 0, 'So, you had any luck yet?', 0),
(40792, 0, 0, 'Has the Aqua Core been recovered?$B$BI know it might take you some time to find, but it is imperative it comes into my possession.', 0),
(40793, 0, 0, 'If it were within my power, I would nail their entire race to stakes and watch the life burn out of them. The way my people burned. The way my father died.', 0),
(40794, 0, 0, 'What is it? Can I help you?', 0),
(40672, 0, 0, 'Have they been overcome, have they been destroyed?!', 0),
(40673, 0, 0, 'It must be done, their leaders must die. They, more than the luckless footsoldiers they throw at us, are at fault for the persecution of our people.$B$BDo not forget it.', 0),
(40674, 0, 0, 'I have not forgotten Alverold\'s heinous pyres. Give him and the last of his expedition what they deserve!', 0),
(40675, 0, 0, 'Here you are. Hail, $N!', 0);
