INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60901, 0, 0, 'Wretched Horde scum! You shall be unended from this earth for all the treachery and misery you have brought to the world!', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Alverold - Turtle text 30046'),
(60901, 1, 0, 'Kul Tiras will never forget the suffering you have brought to Azeroth... You shall never know peace.. as long as the anchor stands...', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Alverold - Turtle text 30047'),
(60900, 0, 0, 'Well done on your missions, recruit. You make Kul Tiras proud!', 12, 0, 100, 0, 0, 0, 0, 0, 'Deckmaster Darkhollow - Turtle text 66598'),
(61026, 200, 0, 'Baha! A true soldier of the Horde! One of grit and steel — those Kul Tirans are no match for you!', 12, 0, 100, 0, 0, 0, 0, 0, 'Warbringer Dar\'nakk - Turtle text 66473'),
(61026, 201, 0, 'Durotar stands strong, no human shall break the might of the Horde!', 12, 0, 100, 0, 0, 0, 0, 0, 'Warbringer Dar\'nakk - Turtle text 66474'),
(61026, 202, 0, 'You have destroyed our foe $N, and showed them true might. I bow in witness of such glory, Lok\'tar', 12, 0, 100, 0, 0, 0, 0, 0, 'Warbringer Dar\'nakk - Turtle text 67029'),
(91259, 0, 0, 'Bottoms up!', 12, 0, 100, 0, 0, 0, 0, 0, 'Pazzle Brightwrench - Turtle text 66994'),
(91259, 1, 0, 'Ack- that hits the spot!', 12, 0, 100, 0, 0, 0, 0, 0, 'Pazzle Brightwrench - Turtle text 66995'),
(91282, 200, 0, 'Finally, I can sleep in a real bed!', 12, 0, 100, 0, 0, 0, 0, 0, 'Shalgrig Pipeshack - Turtle text 66988'),
(91282, 201, 0, 'Well, maybe we can get back to sailing soon, after a nice break! Thanks!', 12, 0, 100, 0, 0, 0, 0, 0, 'Shalgrig Pipeshack - Turtle text 66989'),
(91282, 202, 0, 'Goodluck out there, and may you have the sailors luck!', 12, 0, 100, 0, 0, 0, 0, 0, 'Shalgrig Pipeshack - Turtle text 66990'),
(16399, 200, 0, 'Oh, he did, did he? Well, I might know a thing or two about that, the only crew that would be wanting the head of those goblins would be Captain Salt Tooth, he\'s got a camp to the north near the arena, and that\'s all I know, I swear!', 12, 0, 100, 0, 0, 0, 0, 0, 'Bloodsail Traitor - Turtle text 66987'),
(91297, 0, 0, 'Fine, FINE! Take me back to the hole, just don\'t kill me!', 12, 0, 100, 0, 0, 0, 0, 0, 'Baxxil - Turtle text 91298'),
(91297, 1, 0, 'Okay, okay! Just whatever you say boss!', 12, 0, 100, 0, 0, 0, 0, 0, 'Baxxil - Turtle text 91299'),
(91297, 2, 0, 'Please, no! I have gold, I can p...', 12, 0, 100, 0, 0, 0, 0, 0, 'Baxxil - Turtle text 91300'),
(91249, 0, 0, 'Good! All the damage he caused and now he\'s finally going to pay for it!', 12, 0, 100, 0, 0, 0, 0, 0, 'Hizzle - Turtle text 66188'),
(61973, 0, 0, 'Nobody just simply leaves the Venture Co.! They are all traitors to the Trade Coalition!', 12, 0, 100, 0, 0, 0, 0, 0, 'Suspicious Goblin - Turtle text 30177');
