(9989100, 0, 3, 'Train me.', 0, 5, 16, 0, 0, 0, 0, NULL, 0, 0),
(7236, 200, 0, 'Revilgaz sent me to look for information about the group hunting the Brightwater crew.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0),
(60037, 0, 0, 'You\'re coming back to Sparkwater to serve your sentence.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0),
(60037, 1, 0, 'Prison is too good for scum like you. Time to die.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0),
(60019, 0, 0, 'Here you are Hizzle, I got your prisoner red handed.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0),
(41620, 0, 0, 'What are you doing there? What did you do to Grizzby?', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
